#!/usr/bin/env node
// 把安装脚本烘焙进 Worker 包：/install 与 /install.ps1 由 Worker 以 text/plain 直接吐出，
// 内容在构建时从 scripts/ 读入（不经过静态资源、不会 404、不需要额外托管）。
// scripts/ 是唯一真源：这里只做嵌入，不改一个字节。
import { readFileSync, mkdirSync, writeFileSync, existsSync } from "node:fs";
import { fileURLToPath } from "node:url";

const here = fileURLToPath(new URL(".", import.meta.url));
const shPath = fileURLToPath(new URL("../../scripts/install.sh", import.meta.url));
const ps1Path = fileURLToPath(new URL("../../scripts/install.ps1", import.meta.url));
const outDir = fileURLToPath(new URL("../worker/generated/", import.meta.url));
const outFile = `${outDir}installScripts.ts`;

for (const path of [shPath, ps1Path]) {
  if (!existsSync(path)) throw new Error(`missing installer source: ${path}`);
}

const sh = readFileSync(shPath, "utf8");
const ps1 = readFileSync(ps1Path, "utf8");
const header = "// GENERATED by website/scripts/gen-install-bundle.mjs - edit scripts/install.sh or scripts/install.ps1 instead.\n";

const body = `${header}export const INSTALL_SH = ${JSON.stringify(sh)};\n\nexport const INSTALL_PS1 = ${JSON.stringify(ps1)};\n`;
mkdirSync(outDir, { recursive: true });
writeFileSync(outFile, body);
console.log(`baked installers into ${outFile} (${sh.length} B shell, ${ps1.length} B PowerShell), from ${here}`);
